    'terms.s3.title': '3. Health & Medical Disclaimer',
    'terms.s3.important': 'Our health and wellness apps (including Yantar and Fulcrum) are <strong>not medical applications</strong> and do <strong>not provide medical advice</strong>.',
    'terms.s3.l1': 'These apps are intended for general wellness and informational purposes only.',
