    'values.everyone.title': 'Für Alle Gemacht',
    'values.everyone.text': 'Alle unsere Apps unterstützen mehrere Sprachen und sind mit Barrierefreiheit im Sinn gestaltet.',
    'footer.privacy': 'Datenschutzrichtlinie',
