    'values.title': 'I Nostri Valori',
    'values.privacy.title': 'Privacy Prima di Tutto',
    'values.privacy.text': 'I tuoi dati restano sul tuo dispositivo o nel tuo iCloud personale. Non tracciamo, profiliamo né vendiamo dati. Nessun SDK di analisi, nessuna pubblicità.',
    'values.design.title': 'Design Curato',
    'values.design.text': 'Interfacce pulite che si integrano nativamente con iOS. Ogni interazione è intenzionale, ogni schermata ha uno scopo.',
    'values.everyone.title': 'Per Tutti',
    'values.everyone.text': 'Tutte le nostre app supportano più lingue e sono progettate con l\'accessibilità in mente.',
    'footer.privacy': 'Informativa sulla Privacy',
